import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.Cm6XCzck.js";const h=JSON.parse('{"title":"8. Three-Valued Governance Interpretation","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.7/part-03.md","filePath":"en/publications/implementation-case-i0.7/part-03.md","lastUpdated":1786282064000}'),r={name:"en/publications/implementation-case-i0.7/part-03.md"};function o(d,e,c,s,l,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_8-three-valued-governance-interpretation" tabindex="-1">8. Three-Valued Governance Interpretation <a class="header-anchor" href="#_8-three-valued-governance-interpretation" aria-label="Permalink to &quot;8. Three-Valued Governance Interpretation&quot;">​</a></h1><p>TMPA keeps semantic judgment separate from view classification:</p><table tabindex="0"><thead><tr><th>Judgment</th><th>Typical view</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>Required evidence and applicable rules establish the conclusion.</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>A deterministic violation excludes the affected evidence or action.</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>Evidence is missing or conflicting, or an authorized human decision is still required.</td></tr></tbody></table><p>This distinction is visible in I0.7. Missing acceptance in C06 does not make the work false; it leaves completion undetermined and prevents state advancement. The unauthorized C12 decision is preserved as evidence but is invalid as a conflict-resolving authority act. C08 quarantines tampered covered content while retaining the failed source in the manifest. The Reader therefore reconstructs both usable facts and the reasons other evidence was excluded or deferred.</p><h1 id="_9-reproducibility-and-evidence-quality" tabindex="-1">9. Reproducibility and Evidence Quality <a class="header-anchor" href="#_9-reproducibility-and-evidence-quality" aria-label="Permalink to &quot;9. Reproducibility and Evidence Quality&quot;">​</a></h1><p>The formal V1.4.1 archive contains 68 files. Its outer SHA-256 is <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code>. Archive integrity, the internal payload manifest, strict UTF-8 decoding, JSON and JSONL parsing, and the bundled verification script pass. A redaction scan covered 65 text files and reported no findings.</p><p>The package preserves:</p><ul><li>fixed source identities and checkout state;</li><li>dependency lockfiles and environment metadata;</li><li>exact commands with exit codes and durations;</li><li>raw stdout/stderr and structured run summaries;</li><li>the 15-assertion external product fixture;</li><li>the C01–C14 matrix and canonical actual outputs;</li><li>source excerpts for the S0.5 projection and Reader;</li><li>an internal SHA-256 manifest and evidence verifier.</li></ul><p>One metadata limitation is explicit: <code>environment.json</code> records npm as unavailable because the collector did not resolve the executable name, although the recorded Windows commands invoke <code>npm.cmd</code> successfully and their logs and exit codes are present. This limits the captured npm-version claim; it does not change the executed test verdicts.</p><h1 id="_10-limitations" tabindex="-1">10. Limitations <a class="header-anchor" href="#_10-limitations" aria-label="Permalink to &quot;10. Limitations&quot;">​</a></h1><ol><li>The result is author-run on fixed commits and a fixed bundle; no independent party has rerun or certified it.</li><li>Runtime retains one skipped test, and FCoP retains two historical-example skips under the migrated layout.</li><li>Shell testing used an isolated instance after native initialization; generated files are recorded separately from the source commit.</li><li>C08 demonstrates governance-object integrity handling, not installer self-protection, identity authentication, or factual truth.</li><li>C11 covers four fixed sources and all 24 input permutations; it is not a formal proof for arbitrary source counts or adversarial environments.</li><li>The package is not a claim of representative SME performance, comparative superiority, Byzantine resilience, or third-party adoption.</li><li>WP-13 is a bounded governance case, not a hallucination-elimination benchmark.</li><li>The evidence capture itself created no paper publication, push, release, or tag; those publication acts are governed separately by repository history.</li></ol><h1 id="_11-claim-ledger" tabindex="-1">11. Claim Ledger <a class="header-anchor" href="#_11-claim-ledger" aria-label="Permalink to &quot;11. Claim Ledger&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Claim</th><th>I0.7 disposition</th></tr></thead><tbody><tr><td>TMPA Core S0.5 defines C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.4.1 contains corresponding product mechanisms</td><td><strong>Implemented</strong></td></tr><tr><td>The locked author-run bundle records 14/14 product PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>The result has been independently rerun or certified</td><td><strong>Not demonstrated</strong></td></tr><tr><td>TMPA has been independently adopted by another organization</td><td><strong>Not demonstrated</strong></td></tr><tr><td>WP-13 proves hallucination elimination</td><td><strong>Prohibited conclusion</strong></td></tr></tbody></table><h1 id="_12-engineering-conclusion" tabindex="-1">12. Engineering Conclusion <a class="header-anchor" href="#_12-engineering-conclusion" aria-label="Permalink to &quot;12. Engineering Conclusion&quot;">​</a></h1><p>I0.7 advances the Implementation Case from I0.6&#39;s mixed local product baseline to a clean, publicly retrievable CodeFlowMu V1.4.1 source lock and a complete product-level C01–C14 execution. The formal result is 14 PASS / 0 FAIL under the fixed bundle. The two failures observed in V1.4.0 are closed by preserving the separation between lifecycle and acceptance and by requiring authorized conflict resolution.</p><p>The result is meaningful engineering evidence because it preserves exact sources, commands, outputs, criterion observations, limitations, and repair history. Its boundary is equally important: it demonstrates implementation behavior; it does not prove TMPA theory, certify every CodeFlowMu deployment, or establish independent adoption. FCoP remains the protocol layer, CodeFlowMu the application layer, and WP-13 a bounded governance case.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The formal I0.7 evidence archive is <a href="/joinwell52/evidence/tmpa/i0.7/tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip">tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip</a>. The adjacent file <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip.sha256</code> records <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code>.</p><p>The V1.4.0 12 PASS / 2 FAIL archive is retained as pre-repair historical evidence but is not published as the formal I0.7 main package. The historical I0.6 package and WP-13 V3 remain available at their versioned paths. Git history is the publication history; no parallel paper database has editorial authority.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.5.” GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.7.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” version 3.2.4, commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.4.1,” commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code>. GitHub, 2026.</p><p>[5] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3.” GitHub, 2026.</p><p>[6] TMPA Project. “I0.7 CodeFlowMu V1.4.1 Evidence,” package <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809</code>, 2026.</p>',26)])])}const m=t(r,[["render",o]]);export{h as __pageData,m as default};
